<template>
  <div @scroll="handleScroll">
    <svg :style="svgStyle" :width="radius * 2" :height="radius * 2" :viewBox="`0 0 ${radius * 2} ${radius * 2}`" xmlns="http://www.w3.org/2000/svg">
      <!-- Define the circular path dynamically based on radius -->
      <path :id="'circlePath'" fill="none" stroke="transparent" 
        :d="`M ${radius}, ${radius} m -${radius - 25}, 0 a ${radius - 25},${radius - 25} 0 1,0 ${radius * 2 - 50},0 a ${radius - 25},${radius - 25} 0 1,0 -${radius * 2 - 50},0`"/>
      <!-- Apply text to the circular path with fixed font size -->
      <text :style="{ fontSize: fontSize + 'px' }" fill="black">
        <textPath :xlink:href="'#circlePath'" startOffset="50%" style="text-anchor: middle;">
          {{ message }}
        </textPath>
      </text>
    </svg>
  </div>

</template>

<script>
export default {
  props: {
    message: String,
    radius: Number,
    fontSize: Number
  },
  data() {
    return {
      // Default rotation duration
      rotationDuration: 10,
    };
  },
  computed: {
    // Dynamically generate the SVG style
    svgStyle() {
      return {
        animation: `rotateCircle ${this.rotationDuration}s linear infinite`,
      };
    },
  },
  methods: {
    handleScroll() {
      const scrollPosition = window.scrollY;
      const newDuration = Math.max(5, 30 - scrollPosition / 30);
      
      this.rotationDuration = newDuration;
    },
  },
  mounted() {
    // Add scroll event listener to the window
    window.addEventListener('scroll', this.handleScroll);
  },
  beforeUnmount() {
    // Clean up the event listener when the component is destroyed
    window.removeEventListener('scroll', this.handleScroll);
  },
};
</script>


<style>
@keyframes rotateCircle {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
svg {
  display: block;
  margin: auto;
  background-color: white;
  border-radius: 50%;
  animation: rotateCircle 20s linear infinite;
}


</style>